"""Four bounded easy-card rewrites; explicit six-field author judgments."""
import importlib.util,json,os
from pathlib import Path
R=Path(__file__).resolve().parent
sp=importlib.util.spec_from_file_location('land',R/'author-land4.py');land=importlib.util.module_from_spec(sp);sp.loader.exec_module(land);p=land.p
for name,word in [('paysan','paysan'),('serf','serf'),('artisan','artisan'),('marchand','marchand'),('chevalier-nom','chevalier'),('fermage','fermage'),('fermier','fermier'),('journalier','journalier'),('dime-nom','d%C3%AEme'),('corvee','corv%C3%A9e'),('peage','p%C3%A9age')]:land.urls[name]='https://www.cnrtl.fr/definition/'+word
pr=land.pr;proofs=land.proofs
pr('peasant','paysan','I, definition','Personne de la campagne qui vit de la culture du sol et de l\'élevage des animaux')
pr('artisan','artisan','I.A, general definition, not modern commercial statute','Personne exerçant, pour son propre compte, un art mécanique ou un métier manuel qui exige une certaine qualification professionnelle')
pr('merchant','marchand','I.A','Personne dont la profession est d\'acheter (plus rarement de fabriquer) et de revendre une ou plusieurs sortes de produits en en tirant un bénéfice.')
pr('knight-order','chevalier-nom','I.B.2, Moy. Age occidental; noun entry','Membre d\'un ordre religieux et militaire. Chevalier teutonique; chevalier de Malte, de Rhodes, du Temple.')
pr('serf','serf','I.A, HIST. DU MOY. AGE','Personne attachée à une terre, dont les biens et le travail appartiennent au propriétaire de cette terre (seigneur, roi, communauté religieuse) envers qui elle a des obligations.')
pr('tenant','fermier','A.2 AGRIC.','Personne qui, moyennant une redevance annuelle, a le droit de faire valoir une exploitation agricole')
pr('annual','fermage','Etymologie et histoire','1367 « prix à payer annuellement pour un bail d\'exploitation à ferme »')
pr('day-labour','journalier','II, substantive meaning','Personne engagée pour un travail généralement agricole rémunéré à la journée.')
pr('corvee','corvee','I.A, DR. ANC.','Journées de travail collectives gratuites (d\'hommes et de bêtes de somme) dues au seigneur (jusqu\'en 1789) par les serfs, les roturiers, pour assurer l\'entretien et l\'exploitation de ses biens et domaines.')
pr('tithe','dime-nom','A.2 DR. FEOD., noun entry, not adjective dixieme','Impôt sur les récoltes (de fraction variable, parfois le dixième) prélevé par le clergé ou la noblesse.')
pr('toll','peage','A, old meaning','Droit dont devaient s\'acquitter les usagers de certaines voies ou ouvrages (routes, ponts, rivières) pour eux-mêmes, leurs bêtes, leurs véhicules ou leurs marchandises')
proofs['freehold']=p.kp(4,'Free Hold ','Free Warren ')
proofs['chevage']=p.kp(1,'Chevage ','Chief Rent ')
proofs['capon']=p.kp(1,'Capon ','Cartbote ')
proofs['steward']={**p.kp(6,'Reeve A','Relief '),'locator':{'pdfPage':6,'entry':'Steward'},'passage':p.PDF.pages[5].extract_text().split('Steward Official',1)[0]}
# Exact final entry on PDF page6; do not use the preceding terms as proof.
page=p.PDF.pages[5].extract_text();proofs['steward']['passage']=page[page.index('Steward Official'):].rstrip()
edits={
'middle-ages-peasant':{'prompt':'Кто в средневековом обществе обычно жил сельским хозяйством: обрабатывал поля и выращивал урожай?','answers':[{'text':'Купец','note':'Купец покупал товары и перепродавал их, получая прибыль от торговли.'},{'text':'Рыцарь','note':'Рыцари входили и в духовно-военные ордена, например в Тевтонский орден или орден тамплиеров.'},{'text':'Крестьянин','note':'Крестьянское хозяйство могло включать и разведение скота.'},{'text':'Ремесленник','note':'Ремесленник занимался ручным производством, требовавшим профессионального умения.'}],'explanation':'Основным занятием крестьянина было сельское хозяйство. Он обрабатывал землю и выращивал урожай; торговля и ремесло выделялись как другие занятия.','source':{'title':'CNRTL / TLFi — paysan','url':land.urls['paysan'],'verifiedAt':'2026-10-11'}},
'middle-ages-serf':{'prompt':'Как называли лично зависимого средневекового земледельца, прикреплённого к земле господина?','answers':[{'text':'Подённый батрак','note':'Подённый работник получал плату за каждый день выполненной работы.'},{'text':'Свободный арендатор','note':'Земельный арендатор получал право вести хозяйство за плату собственнику участка.'},{'text':'Крепостной крестьянин','note':'В английских манорах виллан мог платить шеваж за право жить вне манора, где он родился.'},{'text':'Свободный землевладелец','note':'Английский фригольд означал владение землёй, не подчинённое обычаям манора.'}],'explanation':'Такого земледельца называли крепостным крестьянином; в Западной Европе употреблялся термин «серв». Он был прикреплён к земле и нёс обязанности перед её господином.','source':{'title':'CNRTL / TLFi — serf, medieval history','url':land.urls['serf'],'verifiedAt':'2026-10-11'}},
'middle-ages-tenant-farmer':{'prompt':'Кем был земледелец, если получал чужой участок для ведения хозяйства за оговорённую плату его владельцу?','answers':[{'text':'Собственник участка','note':'В английском фригольде держатель владел землёй напрямую, вне обычаев манора.'},{'text':'Управляющий имением','note':'В английском маноре стюард управлял хозяйством от имени лорда.'},{'text':'Арендатор участка','note':'Средневековое французское слово fermage обозначало ежегодную плату за земельную аренду.'},{'text':'Подённый работник','note':'Подённого работника нанимали с оплатой за день труда, обычно для сельскохозяйственных работ.'}],'explanation':'Такой земледелец выступал арендатором участка. Он получал право вести хозяйство на земле владельца за установленную плату.','source':{'title':'CNRTL / TLFi — fermier, agricultural tenant','url':land.urls['fermier'],'verifiedAt':'2026-10-11'}},
'middle-ages-freeman':{'prompt':'Как называлась повинность, при которой крестьянин бесплатно отрабатывал положенные дни в хозяйстве сеньора?','answers':[{'text':'Оброк','note':'Натуральные платежи могли включать птицу: английские держатели по условиям аренды отдавали лорду каплунов к праздникам.'},{'text':'Десятина','note':'Десятину взимали с урожая; её размер мог различаться и не всегда составлял ровно одну десятую.'},{'text':'Пошлина','note':'Проездные пошлины взимали за пользование дорогами, мостами или речными путями, в том числе за провоз товаров.'},{'text':'Барщина','note':'К таким работам привлекали не только людей, но и их вьючных животных.'}],'explanation':'Отработочную повинность в хозяйстве сеньора называли барщиной. Её отличала обязательная безвозмездная работа, а не передача денежного или натурального платежа.','source':{'title':'CNRTL / TLFi — corvée, seigneurial labour service','url':land.urls['corvee'],'verifiedAt':'2026-10-11'}}}
reads={
'middle-ages-peasant':('PASS','Easy: общеизвестное различие сельского хозяйства, торговли, ремесла и рыцарского сословия. Четыре знакомые социальные роли Средневековья; убраны пересекающиеся серв/держатель/свободный крестьянин. Слово обычно не отрицает побочных занятий. Correct-note добавляет скотоводство сверх основного факта о полях и урожае. Все четыре именные подписи согласованы с кто.',[
('prompt-key','PASS',True,'Paysan definition connects rural person and cultivation of soil; crops are the direct meaning of cultivation, not a claim of universal cereal monoculture. The role is phrased usually, so a peasant can also trade or make objects.',['peasant']),
('note0','PASS',True,'Merchant definition explicitly buying and reselling products for profit. Не приписано выращивание как обязательный признак купца.',['merchant']),
('note1','PASS',True,'Noun chevalier I.B.2 explicitly lists religious-military orders including Teutonic and Temple. Checked correct medieval noun entry, not Roman equestrian or modern ring/adjective.',['knight-order']),
('note2','PASS',True,'Paysan definition includes animal husbandry independently of soil cultivation. Additional fact beyond main crop cultivation. Могло avoids compulsory livestock for every household.',['peasant']),
('note3','PASS',True,'Artisan I.A states manual occupation requiring qualification. Note preserves professional skill, omits modern registration rules and commercial legal status.',['artisan']),
('explanation','PASS',True,'Two sentences explain primary farming role and distinguish trade/manual craft by their separately read definitions. No universal prohibition on mixed occupations.',['peasant','merchant','artisan'])]),
'middle-ages-serf':('PASS','Easy: русское крепостной крестьянин понятно широкой взрослой аудитории, в отличие от одного редкого серв. Все четыре варианта относятся к сельским работникам и держателям земли; свободный статус в двух дистракторах исключает смешение арендатора вообще с крепостным арендатором. Вопрос о названии личного статуса. Correct-note добавляет конкретную манориальную плату за переселение. Четыре подписи прочитаны в именительном падеже.',[
('prompt-key','PASS',True,'Serf medieval definition expressly person attached to land and obligations to owner. Крепостной крестьянин is Russian equivalent of medieval unfree agricultural holder, not a modern employee.',['serf']),
('note0','PASS',True,'Journalier II substantive: generally agricultural worker paid by day. Note does not confuse tenure with wages.',['day-labour']),
('note1','PASS',True,'Fermier A2 directly right to cultivate farm against annual due. The option itself says free to avoid pretending all historical tenants were personally free.',['tenant']),
('note2','PASS',True,'Kernow Chevage exact definition payment by villein to lord for right to live outside birth manor. Note restricts English manor and villein, not universal rule for every European serf.',['chevage']),
('note3','PASS',True,'FreeHold definition says held outright, not subject manor customs. Note is a precise English tenure example, not a claim that every free person owned land.',['freehold']),
('explanation','PASS',True,'Two sentences translate serf and explain attachment/obligations. Не приравнивает все права серва к полной римской рабской собственности.',['serf'])]),
'middle-ages-tenant-farmer':('PASS','Easy: обычное понимание аренды доступно большинству взрослых. Четыре роли относительно участка/работы: собственник, управляющий, арендатор, подённый работник; direction of payment and right to cultivate distinguishes renter. Убрана неоднозначная формулировка держатель, включавшая и иные режимы. Correct-note adds annual medieval term rather than repeating pay for use. All four nominative labels read consistently.',[
('prompt-key','PASS',True,'Fermier agricultural definition gives right to operate farm for annual due; the key renter captures the exact role. No claim that any service obligation always equals rent.',['tenant']),
('note0','PASS',True,'English freehold held outright/not manor customs is a concrete ownership-type example for owner option. Not extrapolated to all jurisdictions.',['freehold']),
('note1','PASS',True,'Steward is official running manor on lord behalf. This is management rather than tenant paying for own farming right.',['steward']),
('note2','PASS',True,'Fermage etymological entry documents1367 price payable annually for farm lease. Supports medieval French term and annual payment, additional temporal detail beyond generic rental.',['annual']),
('note3','PASS',True,'Journalier definition states pay per day and generally agricultural work. Both clauses preserved without claiming every casual labourer agricultural.',['day-labour']),
('explanation','PASS',True,'Two sentences name renter and identify right of farming against agreed payment. No unsupported ownership transfer or personal freedom universalization.',['tenant'])]),
'middle-ages-freeman':('PASS','Easy: школьное общеизвестное понятие барщина; четыре близких вида средневековых повинностей и платежей. Нужно отличить работу от натуральных/денежных сборов. Исходное тавтологическое свободный крестьянин заменено новым основным фактом; в общем каталоге барщина/оброк в главных фактах не найдены. Correct-note adds use of burden animals. Все варианты — существительные в именительном падеже.',[
('prompt-key','PASS',True,'Corvee old-law definition states unpaid days of collective work owed to lord to maintain/exploit estate. Барщина accurately names seigneurial labour duty in Russian, distinct from modern military chores.',['corvee']),
('note0','PASS',True,'Kernow Capon: lease-condition payment to lord at Michaelmas/Christmas as castrated cocks. Concrete English example of payment in kind, not mistaken claim that obrok was compulsory unpaid days.',['capon']),
('note1','PASS',True,'Dime noun feudal definition explicitly variable share sometimes tenth; note avoids false universal exactly10percent. Correct noun entry selected, not adjective dixieme.',['tithe']),
('note2','PASS',True,'Peage old definition lists roads, bridges, rivers and goods; note precisely about transit toll category, without importing modern motorway financing.',['toll']),
('note3','PASS',True,'Corvee definition specifies hommes et betes de somme. Additional participants/equipment beyond human work days in prompt. Вьючные directly translates betes de somme.',['corvee']),
('explanation','PASS',True,'Two sentences identify unpaid seigneurial labour and distinguish it from cash/kind payments. Work property derives from corvee and concrete kind payment from capon.',['corvee','capon'])])}
def emit():
 topic=json.loads(p.TOPIC.read_text());by={c['id']:c for c in topic['questions']};receipt={'role':'author','agentIdentity':os.environ['CODEX_THREAD_ID'],'status':'AUTHOR_CANDIDATE_ONLY; not independent certification','cards':[]}
 for qid,edit in edits.items():
  c=by[qid];c.update(edit);v,editorial,rows=reads[qid];rec={'questionId':qid,'cardCanonicalSha256':p.digest(p.canon(c)),'verdict':v,'editorialAnalysis':editorial,'literalSnapshot':c,'grammarSubstitutions':[c['prompt']+' — '+a['text']+'.' for a in c['answers']],'fields':[]}
  for name,v,read,analysis,refs in rows:
   lit=[c['prompt'],c['correctIndex'],c['answers'][c['correctIndex']]['text']] if name=='prompt-key' else c['explanation'] if name=='explanation' else c['answers'][int(name[-1])]['note'];f={'field':name,'verdict':v,'substantiveRead':read,'claimAnalysis':analysis,'literal':lit,'literalSha256':p.digest(p.canon(lit) if isinstance(lit,list) else lit.encode()),'proofs':[]}
   for ref in refs:
    z=dict(proofs[ref]);z.update(proofId=ref,rawCaptureSha256=p.digest((R/z['rawCapture']).read_bytes()),passageSha256=p.digest(z['passage'].encode()));f['proofs'].append(z)
   rec['fields'].append(f)
  receipt['cards'].append(rec)
 p.TOPIC.write_text(json.dumps(topic,ensure_ascii=False,indent=2)+'\n');(R/'author-peasants4.json').write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');(R/'peasants4-candidate.json').write_text(json.dumps([by[q] for q in edits],ensure_ascii=False,indent=2)+'\n')
if __name__=='__main__':emit()
